"""Build ten original, unreviewed, bounded conversation rehearsals.

These rehearsals extend the named topic without changing its original text.
The fixed replies introduce any additional fictional details explicitly.
Run from any directory; no network or model calls are made.
"""
from __future__ import annotations

import json
from pathlib import Path


def loc(nl: str, en: str, fa: str) -> dict[str, str]:
    return {"nl": nl, "en": en, "fa": fa}


def choice(key: str, label: dict, aliases: list[str], valid: bool) -> dict:
    return {"id": key.replace("_", "-"), "label": label, "aliases": aliases, "valid": valid}


def step(key, goal, cue, hint, accepted, groups, example, choices=None):
    return {
        "id": key.replace("_", "-"), "goal": goal, "cue": cue, "hint": hint,
        "accepted": accepted, "required_groups": groups,
        "choices": choices or [], "example": example,
    }


def conversation(stage, number, title, role, setup, opening, success, steps):
    topic = f"{stage}-t{number:03d}"
    return {
        "id": f"{topic}-conversation", "stage_id": stage, "topic_id": topic,
        "title": title, "role": role, "setup": setup, "opening": opening,
        "success": success, "steps": steps,
    }


