def main() -> None:
    root = Path(__file__).resolve().parents[2]
    path = root / "content" / "conversations" / "pilot.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = {"schema_version": 1, "review_status": "unreviewed", "conversations": CONVERSATIONS}
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {len(CONVERSATIONS)} conversation rehearsals to {path.relative_to(root)}")


if __name__ == "__main__":
    main()
